export async function getClaimInstructionAsync<
  TAccountAuthority extends InstructionSignerInput,
  TAccountGame extends InstructionAccountInput,
  TAccountRewards extends InstructionAccountInput,
  TAccountPlayer extends InstructionAccountInput,
  TAccountHolder extends InstructionAccountInput,
  TProgramAddress extends Address = typeof SKECH_PROGRAM_ADDRESS,
>(
  input: ClaimAsyncInput<
    TAccountAuthority,
    TAccountGame,
    TAccountRewards,
    TAccountPlayer,
    TAccountHolder
  >,
  config?: { programAddress?: TProgramAddress },
): Promise<
  ClaimInstruction<
    TProgramAddress,
    ResolvedInstructionAccountMeta<
      TAccountAuthority,
      InstructionAccountInputAddress<TAccountAuthority>
    >,
    ResolvedInstructionAccountMeta<
      TAccountGame,
      InstructionAccountInputAddress<TAccountGame>
    >,
    ResolvedInstructionAccountMeta<
      TAccountRewards,
      InstructionAccountInputAddress<TAccountRewards>
    >,
    ResolvedInstructionAccountMeta<
      TAccountPlayer,
      InstructionAccountInputAddress<TAccountPlayer>
    >,
    ResolvedInstructionAccountMeta<
      TAccountHolder,
      InstructionAccountInputAddress<TAccountHolder>
    >
  >
> {
  // Program address.
  const programAddress = config?.programAddress ?? SKECH_PROGRAM_ADDRESS;

  // Account meta helper.
  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");

  // Original accounts.
  const originalAccounts = {
    authority: {
      value: input.authority ?? null,
      isSigner: true,
      isWritable: false,
    },
    game: { value: input.game ?? null, isSigner: false, isWritable: false },
    rewards: {
      value: input.rewards ?? null,
      isSigner: false,
      isWritable: true,
    },
    player: { value: input.player ?? null, isSigner: false, isWritable: true },
    holder: { value: input.holder ?? null, isSigner: false, isWritable: true },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedInstructionAccount
  >;

  // Resolve default values.
  if (!accounts.game.value) {
    accounts.game.value = await findGamePda({ programAddress });
  }
  if (!accounts.player.value) {
    accounts.player.value = await findPlayerPda(
      {
        authority: getAddressFromResolvedInstructionAccount(
          "authority",
          accounts.authority.value,
        ),
      },
      { programAddress },
    );
  }

  return Object.freeze({
    accounts: [
      getAccountMeta("authority", accounts.authority),
      getAccountMeta("game", accounts.game),
      getAccountMeta("rewards", accounts.rewards),
      getAccountMeta("player", accounts.player),
      getAccountMeta("holder", accounts.holder),
    ],
    data: getClaimInstructionDataEncoder().encode({}),
    programAddress,
  } as ClaimInstruction<
    TProgramAddress,
    ResolvedInstructionAccountMeta<
      TAccountAuthority,
      InstructionAccountInputAddress<TAccountAuthority>
    >,
    ResolvedInstructionAccountMeta<
      TAccountGame,
      InstructionAccountInputAddress<TAccountGame>
    >,
    ResolvedInstructionAccountMeta<
      TAccountRewards,
      InstructionAccountInputAddress<TAccountRewards>
    >,
    ResolvedInstructionAccountMeta<
      TAccountPlayer,
      InstructionAccountInputAddress<TAccountPlayer>
    >,
    ResolvedInstructionAccountMeta<
      TAccountHolder,
      InstructionAccountInputAddress<TAccountHolder>
    >
  >);
}

